use serde_json::json;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = json!([]);
    let mut left_map: std::collections::HashMap<i64, std::collections::HashSet<i64>> = std::collections::HashMap::new();
    let mut right_map: std::collections::HashMap<i64, std::collections::HashSet<i64>> = std::collections::HashMap::new();

    for row in input["input"].as_array().unwrap().iter() {
        let mut left_set: std::collections::HashSet<i64> = std::collections::HashSet::new();
        let mut right_set: std::collections::HashSet<i64> = std::collections::HashSet::new();

        for (key, value) in row.iter() {
            left_set.insert(*key);
            right_set.insert(*key);
            if let Some(left_value) = left_map.get_mut(key) {
                left_value.insert(*value);
            } else {
                left_map.insert(*key, left_set);
            }
            if let Some(right_value) = right_map.get_mut(key) {
                right_value.insert(*value);
            } else {
                right_map.insert(*key, right_set);
            }
        }

        result = json!([*key, *value, *left_value, *right_value]);
    }

    result
}
